import gurobipy as gp
from gurobipy import GRB
customer_demands = {}
supplier_capacities = {}
transportation_costs = {}
customers = []
suppliers = []
for rec in LEGACY_RECORDS:
    if rec['source'] == 'customer_demand.csv':
        cust = rec['values']['Customers']
        customers.append(cust)
        customer_demands[cust] = int(rec['values']['demand'])
    elif rec['source'] == 'supply_capacity.csv':
        sup = rec['values']['Supplier']
        suppliers.append(sup)
        supplier_capacities[sup] = int(rec['values']['supply_capacity'])
supply_to_supplier = {}
for i, sup in enumerate(suppliers):
    supply_to_supplier[f'supply{i + 1}'] = sup
for rec in LEGACY_RECORDS:
    if rec['source'] == 'transportation_costs.csv':
        supply = rec['values']['Unnamed: 0']
        if supply not in supply_to_supplier:
            raise ValueError(f'Unknown supply row: {supply}')
        sup = supply_to_supplier[supply]
        if sup not in transportation_costs:
            transportation_costs[sup] = {}
        for cust in customers:
            if cust not in rec['values']:
                raise ValueError(f'Missing cost for {supply}, {cust}')
            transportation_costs[sup][cust] = float(rec['values'][cust])
for sup in suppliers:
    if sup not in transportation_costs:
        raise ValueError(f'Missing cost row for {sup}')
    for cust in customers:
        if cust not in transportation_costs[sup]:
            raise ValueError(f'Missing cost for {sup}, {cust}')
m = gp.Model('Amazon_Distribution')
x = m.addVars(suppliers, customers, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((transportation_costs[sup][cust] * x[sup, cust] for sup in suppliers for cust in customers)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x[sup, cust] for sup in suppliers)) == customer_demands[cust] for cust in customers), name='')
m.addConstrs((gp.quicksum((x[sup, cust] for cust in customers)) <= supplier_capacities[sup] for sup in suppliers), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')